export class GSTT implements flatbuffers.IGeneratedObject {
constructor(
  public STATION_ID: string|Uint8Array|null = null,
  public NAME: string|Uint8Array|null = null,
  public NETWORK: gstNetwork = gstNetwork.UNSPECIFIED,
  public DOMES_NUMBER: string|Uint8Array|null = null,
  public CDP_NUMBER: string|Uint8Array|null = null,
  public FRAME_REALIZATION: gstFrameRealization = gstFrameRealization.UNSPECIFIED,
  public FRAME_REALIZATION_NAME: string|Uint8Array|null = null,
  public REFERENCE_EPOCH: string|Uint8Array|null = null,
  public POSITION_X: number = 0.0,
  public POSITION_Y: number = 0.0,
  public POSITION_Z: number = 0.0,
  public VELOCITY_X: number = 0.0,
  public VELOCITY_Y: number = 0.0,
  public VELOCITY_Z: number = 0.0,
  public POSITION_SIGMA_X: number = 0.0,
  public POSITION_SIGMA_Y: number = 0.0,
  public POSITION_SIGMA_Z: number = 0.0,
  public ANTENNA_AXIS_TYPE: gstAntennaAxisType = gstAntennaAxisType.UNSPECIFIED,
  public AXIS_OFFSET_M: number = 0.0,
  public ECCENTRICITY_X: number = 0.0,
  public ECCENTRICITY_Y: number = 0.0,
  public ECCENTRICITY_Z: number = 0.0,
  public ECCENTRICITY_FRAME: string|Uint8Array|null = null,
  public TRANSMIT_BANDS: (string)[] = [],
  public RECEIVE_BANDS: (string)[] = [],
  public CLOCK_OFFSET_S: number = 0.0,
  public CLOCK_RATE_S_PER_S: number = 0.0,
  public CLOCK_TIME_SCALE: string|Uint8Array|null = null,
  public VALID_FROM: string|Uint8Array|null = null,
  public VALID_TO: string|Uint8Array|null = null,
  public SOURCE: string|Uint8Array|null = null
){}


pack(builder:flatbuffers.Builder): flatbuffers.Offset {
  const STATION_ID = (this.STATION_ID !== null ? builder.createString(this.STATION_ID!) : 0);
  const NAME = (this.NAME !== null ? builder.createString(this.NAME!) : 0);
  const DOMES_NUMBER = (this.DOMES_NUMBER !== null ? builder.createString(this.DOMES_NUMBER!) : 0);
  const CDP_NUMBER = (this.CDP_NUMBER !== null ? builder.createString(this.CDP_NUMBER!) : 0);
  const FRAME_REALIZATION_NAME = (this.FRAME_REALIZATION_NAME !== null ? builder.createString(this.FRAME_REALIZATION_NAME!) : 0);
  const REFERENCE_EPOCH = (this.REFERENCE_EPOCH !== null ? builder.createString(this.REFERENCE_EPOCH!) : 0);
  const ECCENTRICITY_FRAME = (this.ECCENTRICITY_FRAME !== null ? builder.createString(this.ECCENTRICITY_FRAME!) : 0);
  const TRANSMIT_BANDS = GST.createTransmitBandsVector(builder, builder.createObjectOffsetList(this.TRANSMIT_BANDS));
  const RECEIVE_BANDS = GST.createReceiveBandsVector(builder, builder.createObjectOffsetList(this.RECEIVE_BANDS));
  const CLOCK_TIME_SCALE = (this.CLOCK_TIME_SCALE !== null ? builder.createString(this.CLOCK_TIME_SCALE!) : 0);
  const VALID_FROM = (this.VALID_FROM !== null ? builder.createString(this.VALID_FROM!) : 0);
  const VALID_TO = (this.VALID_TO !== null ? builder.createString(this.VALID_TO!) : 0);
  const SOURCE = (this.SOURCE !== null ? builder.createString(this.SOURCE!) : 0);

  return GST.createGST(builder,
    STATION_ID,
    NAME,
    this.NETWORK,
    DOMES_NUMBER,
    CDP_NUMBER,
    this.FRAME_REALIZATION,
    FRAME_REALIZATION_NAME,
    REFERENCE_EPOCH,
    this.POSITION_X,
    this.POSITION_Y,
    this.POSITION_Z,
    this.VELOCITY_X,
    this.VELOCITY_Y,
    this.VELOCITY_Z,
    this.POSITION_SIGMA_X,
    this.POSITION_SIGMA_Y,
    this.POSITION_SIGMA_Z,
    this.ANTENNA_AXIS_TYPE,
    this.AXIS_OFFSET_M,
    this.ECCENTRICITY_X,
    this.ECCENTRICITY_Y,
    this.ECCENTRICITY_Z,
    ECCENTRICITY_FRAME,
    TRANSMIT_BANDS,
    RECEIVE_BANDS,
    this.CLOCK_OFFSET_S,
    this.CLOCK_RATE_S_PER_S,
    CLOCK_TIME_SCALE,
    VALID_FROM,
    VALID_TO,
    SOURCE
  );
}
}
